  body.append(el("h3","","Toàn bộ KPI trong domain"),para("Chưa có approved targets cho các nguồn này. Tăng/giảm là biến động quan sát, chưa tự phân loại tốt/xấu."));const metrics=table(["KPI","Actual","Comparison","Formula / support","Interpretation"],r.metrics.map(m=>[m.name,kpiDisplay(m.value,m.unit),comparison(m.comparison),m.formula,m.interpretation]));metrics.id="kpi-analysis-metrics";body.append(metrics);
  if(r.decomposition)body.append(note(r.decomposition.formula+". "+r.decomposition.convention));
  if(r.region_bridge)body.append(note(r.region_bridge.formula+". "+r.region_bridge.interpretation+" Reconciliation: "+r.region_bridge.reconciliation+"; Δ USD exact = "+r.region_bridge.total_delta_exact));
  body.append(el("h3","","Dữ liệu chi tiết hỗ trợ phân tích"),para("Mỗi bảng giữ population và đơn vị riêng. Mở bảng để đối chiếu tử số, mẫu số, segments và evidence; không cộng các nguồn khác grain."));r.tables.forEach((t,i)=>{const section=el("details","monitor-inspection kpi-source-table");section.open=i===0;section.append(append(el("summary"),el("span","",t.title),el("small","kpi-table-count"," · "+t.rows.length+" dòng")),table(t.columns,t.rows));body.append(section);});
  if(r.issuer_scopes){const links=el("div","toolbar");r.issuer_scopes.forEach(s=>{const a=el("a","button secondary",s.ticker+" · Filing evidence ↗");a.href="/?"+new URLSearchParams({view:"sec",workspace_tab:"evidence",sec_view_id:s.view_id,sec_cik:s.cik,sec_accession:s.accession??"",sec_asof:s.asof});const trend=el("a","button secondary",s.ticker+" · Annual trends ↗");trend.href="/?"+new URLSearchParams({view:"sec",workspace_tab:"trends",sec_view_id:s.view_id,sec_cik:s.cik,sec_asof:s.asof,sec_trend_years:"5"});links.append(a,trend);});body.append(links);}
  if(r.data_quality){const q=r.data_quality,quality=el("section","kpi-data-quality");quality.append(el("h3","","Chất lượng dữ liệu & phạm vi kiểm tra"),para(q.scope),table(["Control / KPI","Actual","Formula / support","Interpretation"],q.metrics.map(m=>[m.name,kpiDisplay(m.value,m.unit),m.formula,m.interpretation])));q.findings.forEach(f=>quality.append(para(f)));q.tables.forEach(t=>{const d=el("details","monitor-inspection kpi-source-table");d.append(el("summary","",t.title),table(t.columns,t.rows));quality.append(d);});body.append(quality);}
  renderMonitorReviews(body,r.review_snapshot);
  const gaps={P1:[["Application approval / reject rate","Accepted / decisioned applications","Cần application decisions, reject population và decision dates; booked UCI cohort không đủ."],["Economic profit / policy cost","Action×outcome costs + exposure/pricing/funding","Policy workflow đã có declared-cost preview; chưa actual realized profit inputs."],["Drift / OOT stability","Compatible reference vs later cohort","Cần temporal cohorts, feature/score logs và mature labels."]],P2:[["Calibrated PD12","Model probability cho target/horizon đã qualified","Chưa fitted/validated horizon model và temporal vintages; observed D3 share không thay PD."],["Qualified LGD / EL","LGD loss definition; EL=PD×LGD×EAD theo contract","Loss subset/support gates đang blocked; reported loss không thay qualified LGD."],["Cure / migration detail","Adjacent-state/cure episode contracts","Đã có transition/lifecycle workspace; không suy từ monthly stock movement."]],P3:[["DSCR / interest coverage / leverage","Cashflow/debt service, earnings/interest, debt/earnings","Cần filing-specific facts và conventions. SEC issuer workspace là nguồn riêng, không join SBA borrowers tự động."],["Bankruptcy probability","Saved UCI365 one-year benchmark","Đã có Bankruptcy model workspace riêng; không gán benchmark probabilities cho SEC/SBA entities."],["Covenant headroom","Observed ratio − contractual threshold","Cần borrower financials và actual legal covenant terms."]],P4:[["Qualified EAD / PD / LGD / EL","Exposure/risk parameter contract","Source principal không là EAD; source EL null. Declared scenario engine có assumptions riêng."],["IFRS9 ECL / staging","Marginal default, cashflow loss, discounting, SICR","Conditional ECL workspace đã có; chưa qualified institution staging/economic inputs."],["VaR / ES / economic capital","Loss distribution quantiles / tail means","Research tail engine đã có; không derive từ geographic HHI hoặc principal total."]],P5:[["Forward expected cashflows / valuation","Collateral projection + full legal waterfall + discounting","Historical reported replay không là forward forecast."],["OC/IC trigger compliance","Verified contractual trigger tests","Adjusted pool surplus không thay complete legal trigger rules."],["Duration / DV01 / spread sensitivity","Instrument cashflows and price sensitivities","Assumption-only Bond scenarios workspace đã có; chưa actual-security valuation/credit curve."]]};
